function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TicTacToe' || args[0].length !== 1) return 'Start with TicTacToe and one argument, n.';
  const n = args[0][0];
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is a whole number from 2 to 100.';
  if (operations.length - 1 > n * n) return 'At most n^2 moves can be made.';
  const used = new Set();
  const counts = { 1: new Map(), 2: new Map() };
  let over = false;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'move') return 'Only move can follow the constructor.';
    if (args[i].length !== 3 || !args[i].every(Number.isInteger)) return 'move takes three whole numbers: row, col and player.';
    const [row, col, player] = args[i];
    if (row < 0 || row >= n || col < 0 || col >= n) return 'row and col must be inside the board.';
    if (player !== 1 && player !== 2) return 'player is 1 or 2.';
    if (over) return 'No move can be made after a player has won.';
    const cell = row * n + col;
    if (used.has(cell)) return 'Each move must use an empty cell.';
    used.add(cell);
    const keys = ['r' + row, 'c' + col];
    if (row === col) keys.push('d');
    if (row + col === n - 1) keys.push('a');
    for (const key of keys) {
      const total = (counts[player].get(key) || 0) + 1;
      counts[player].set(key, total);
      if (total === n) over = true;
    }
  }
  return null;
}

