class TicTacToe {
  constructor(n) {
    this.n = n;
    this.rows = new Array(n).fill(0);
    this.cols = new Array(n).fill(0);
    this.diagonal = 0;
    this.antiDiagonal = 0;
  }

  move(row, col, player) {
    const delta = player === 1 ? 1 : -1;
    this.rows[row] += delta;
    this.cols[col] += delta;
    if (row === col) {
      this.diagonal += delta;
    }
    if (row + col === this.n - 1) {
      this.antiDiagonal += delta;
    }
    const target = delta * this.n;
    if (this.rows[row] === target || this.cols[col] === target) {
      return player;
    }
    if (this.diagonal === target || this.antiDiagonal === target) {
      return player;
    }
    return 0;
  }
}

