class TicTacToe {
  constructor(n) {
    this.board = Array.from({ length: n }, () => new Array(n).fill(0));
  }
  move(row, col, player) {
    const board = this.board, n = board.length;
    board[row][col] = player;
    const lines = [];
    for (let i = 0; i < n; i++) {
      lines.push(board[i]);
      lines.push(board.map(r => r[i]));
    }
    lines.push(board.map((r, i) => r[i]));
    lines.push(board.map((r, i) => r[n - 1 - i]));
    return lines.some(line => line.every(cell => cell === player)) ? player : 0;
  }
}

