function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 4);
  const limit = size === 'large' ? 1999 : n * n;
  const cells = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) cells.push([r, c]);
  for (let i = cells.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [cells[i], cells[j]] = [cells[j], cells[i]];
  }
  // Often one player aims at a chosen line so that wins happen; the other plays elsewhere.
  const kind = Math.floor(rand() * 5);
  const fixed = Math.floor(rand() * n);
  const onLine = ([r, c]) => kind === 0 ? r === fixed : kind === 1 ? c === fixed : kind === 2 ? r === c : kind === 3 ? r + c === n - 1 : false;
  const aimer = rand() < 0.5 ? 1 : 2;
  const target = cells.filter(onLine);
  const others = cells.filter(cell => !onLine(cell));
  const used = new Set();
  const take = list => { while (list.length && used.has(list[list.length - 1].join())) list.pop(); return list.pop(); };
  const counts = { 1: new Map(), 2: new Map() };
  const bump = (player, key) => { const m = counts[player]; m.set(key, (m.get(key) || 0) + 1); return m.get(key) === n; };
  const operations = ['TicTacToe'];
  const args = [[n]];
  const moves = Math.min(limit, 1 + Math.floor(rand() * n * n));
  const alternate = rand() < 0.8;
  let player = rand() < 0.5 ? 1 : 2;
  for (let k = 0; k < moves; k++) {
    if (!alternate) player = rand() < 0.5 ? 1 : 2;
    const cell = (player === aimer ? take(target) || take(others) : take(others) || take(target));
    if (!cell) break;
    used.add(cell.join());
    const [r, c] = cell;
    operations.push('move');
    args.push([r, c, player]);
    let won = bump(player, 'r' + r);
    won = bump(player, 'c' + c) || won;
    if (r === c) won = bump(player, 'd') || won;
    if (r + c === n - 1) won = bump(player, 'a') || won;
    if (won) break;
    player = 3 - player;
  }
  return [operations, args];
}
